import json

game_state = {
    'running': False,
    'player_score': 0,
    'computer_score': 0,
    'paddle_position': {'y': 160},  # 初始位置在畫布中央
}


def handle(method, path, body):
    global game_state

    if path == '/game/start' and method == 'POST':
        game_state['running'] = True
        return (200, {'message': '遊戲已開始'})

    elif path == '/game/update' and method == 'PUT':
        data = json.loads(body)
        # 這裡可以更新遊戲狀態，但由於我們使用記憶體儲存，
        # 這裡的邏輯主要用於處理遊戲邏輯
        return (200, {'message': '遊戲狀態已更新'})

    elif path == '/game/score' and method == 'GET':
        return (200, {
            'player_score': game_state['player_score'],
            'computer_score': game_state['computer_score']
        })

    elif path == '/game/reset' and method == 'POST':
        game_state['running'] = False
        game_state['player_score'] = 0
        game_state['computer_score'] = 0
        game_state['paddle_position']['y'] = 160
        return (200, {'message': '遊戲已重置'})

    elif path == '/paddle/move' and method == 'PUT':
        data = json.loads(body)
        if 'y' in data:
            game_state['paddle_position']['y'] = data['y']
        elif 'direction' in data:
            # 根據方向移動球拍
            current_y = game_state['paddle_position']['y']
            if data['direction'] == 'up':
                game_state['paddle_position']['y'] = max(0, current_y - 10)
            elif data['direction'] == 'down':
                game_state['paddle_position']['y'] = min(320, current_y + 10)
        return (200, {'message': '球拍位置已更新'})

    else:
        return (404, {'error': '端點未找到'})

