const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// 遊戲狀態
let gameRunning = false;
let playerScore = 0;
let computerScore = 0;

// 球拍和球的屬性
let paddleWidth = 10;
let paddleHeight = 80;
let ballSize = 10;

let playerPaddle = {
    x: 20,
    y: canvas.height / 2 - paddleHeight / 2,
    width: paddleWidth,
    height: paddleHeight,
    speed: 8
};

let computerPaddle = {
    x: canvas.width - 30,
    y: canvas.height / 2 - paddleHeight / 2,
    width: paddleWidth,
    height: paddleHeight,
    speed: 6
};

let ball = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    size: ballSize,
    dx: 5,
    dy: 5,
    speed: 5
};

// 初始化遊戲
function initGame() {
    playerScore = 0;
    computerScore = 0;
    updateScore();
    resetBall();
    gameRunning = true;
}

// 重置球的位置
function resetBall() {
    ball.x = canvas.width / 2;
    ball.y = canvas.height / 2;

    // 隨機方向
    ball.dx = (Math.random() > 0.5 ? 1 : -1) * ball.speed;
    ball.dy = (Math.random() * 2 - 1) * ball.speed;
}

// 更新得分顯示
function updateScore() {
    document.getElementById('player-score').textContent = `玩家: ${playerScore}`;
    document.getElementById('computer-score').textContent = `電腦: ${computerScore}`;
}

// 繪製遊戲元素
function draw() {
    // 清除畫布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 繪製球拍
    ctx.fillStyle = '#000';
    ctx.fillRect(playerPaddle.x, playerPaddle.y, playerPaddle.width, playerPaddle.height);
    ctx.fillRect(computerPaddle.x, computerPaddle.y, computerPaddle.width, computerPaddle.height);

    // 繪製球
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.size, 0, Math.PI * 2);
    ctx.fillStyle = '#000';
    ctx.fill();
    ctx.closePath();
}

// 更新遊戲狀態
function update() {
    if (!gameRunning) return;

    // 移動球
    ball.x += ball.dx;
    ball.y += ball.dy;

    // 球碰到上下邊界
    if (ball.y - ball.size < 0 || ball.y + ball.size > canvas.height) {
        ball.dy = -ball.dy;
    }

    // 球碰到球拍
    if (
        ball.x - ball.size < playerPaddle.x + playerPaddle.width &&
        ball.y > playerPaddle.y &&
        ball.y < playerPaddle.y + playerPaddle.height &&
        ball.dx < 0
    ) {
        ball.dx = -ball.dx;
        // 根據球拍位置調整球的方向和速度
        let hitPosition = (ball.y - (playerPaddle.y + playerPaddle.height / 2)) / (playerPaddle.height / 2);
        ball.dy = hitPosition * 5;
    }

    if (
        ball.x + ball.size > computerPaddle.x &&
        ball.y > computerPaddle.y &&
        ball.y < computerPaddle.y + computerPaddle.height &&
        ball.dx > 0
    ) {
        ball.dx = -ball.dx;
        // 根據球拍位置調整球的方向和速度
        let hitPosition = (ball.y - (computerPaddle.y + computerPaddle.height / 2)) / (computerPaddle.height / 2);
        ball.dy = hitPosition * 5;
    }

    // 球出界
    if (ball.x < 0) {
        computerScore++;
        updateScore();
        resetBall();
    } else if (ball.x > canvas.width) {
        playerScore++;
        updateScore();
        resetBall();
    }

    // 電腦球拍追蹤球
    computerPaddle.y += (ball.y - (computerPaddle.y + computerPaddle.height / 2)) * 0.05;

    // 限制電腦球拍移動範圍
    if (computerPaddle.y < 0) {
        computerPaddle.y = 0;
    } else if (computerPaddle.y + computerPaddle.height > canvas.height) {
        computerPaddle.y = canvas.height - computerPaddle.height;
    }

    // 更新畫面
    draw();
}

// 遊戲主循環
function gameLoop() {
    update();
    requestAnimationFrame(gameLoop);
}

// 控制球拍移動
function movePaddle(direction) {
    if (!gameRunning) return;

    fetch('api/paddle/move', {
        method: 'PUT',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ direction })
    });
}

// 開始遊戲
function startGame() {
    if (gameRunning) return;

    fetch('api/game/start', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        }
    }).then(response => response.json()).then(data => {
        initGame();
    });
}

// 重置遊戲
function resetGame() {
    fetch('api/game/reset', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        }
    }).then(response => response.json()).then(data => {
        initGame();
    });
}

// 設置事件監聽器
document.getElementById('startBtn').addEventListener('click', startGame);
document.getElementById('resetBtn').addEventListener('click', resetGame);

// 鼠標控制球拍
canvas.addEventListener('mousemove', (e) => {
    if (!gameRunning) return;

    const rect = canvas.getBoundingClientRect();
    const mouseY = e.clientY - rect.top;

    playerPaddle.y = mouseY - playerPaddle.height / 2;

    // 限制球拍移動範圍
    if (playerPaddle.y < 0) {
        playerPaddle.y = 0;
    } else if (playerPaddle.y + playerPaddle.height > canvas.height) {
        playerPaddle.y = canvas.height - playerPaddle.height;
    }

    // 發送球拍位置更新到伺服器
    fetch('api/paddle/move', {
        method: 'PUT',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ y: playerPaddle.y })
    });
});

// 初始化遊戲
initGame();
gameLoop();

